-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.quota_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  n integer;
  -- In UTC, whatever the session's time zone (see user_quotas.day).
  today date := (now() at time zone 'UTC')::date;
begin
  insert into public.user_quotas as q (user_id, day, changes_today) values (new.user_id, today, 1)
  on conflict (user_id) do update set
    changes_today = case when q.day = today then q.changes_today + 1 else 1 end,
    day = today
  returning q.changes_today into n;
  if n > 50000 then
    raise exception 'quota_exceeded' using errcode = 'P0001', detail = 'changes';
  end if;
  return null;
end;
$function$;

grant execute on function public.quota_changes() to service_role;
